#!/usr/bin/env node
/**
 * validate-slice-freshness.mjs — detects monolith files edited without running split
 *
 * ROOT CAUSE: behavioral-contracts.md / audit-runner.md / principles.yaml / ai-behavior-spine.md
 * are monolith SSoTs. Their slice files are generated by split generators. If someone edits
 * the monolith but forgets to run `pnpm contracts:split`, the slices become stale.
 * The sync validators (validate-behavioral-contract-slices.mjs etc.) check COUNT but not
 * whether the CONTENT of slices matches the monolith.
 *
 * Per EP-009 (Slice-Drift pattern) + B_CONSOLIDATION_PASS (edit monolith + run split).
 *
 * What it checks:
 *   For each monolith+slices_dir pair: if monolith mtime > newest_slice mtime → WARN
 *   (monolith was modified after slices were last generated)
 *
 * EXIT-CODED: 0 = slices fresh / 1 = stale slices detected
 */

import { statSync, readdirSync, existsSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '../..');

const MONOLITH_SLICE_PAIRS = [
  {
    monolith: 'docs/plan/pillar-0-governance/behavioral-contracts.md',
    slices_dir: 'docs/plan/pillar-0-governance/behavioral-contracts',
    split_cmd: 'pnpm contracts:split',
    name: 'behavioral-contracts',
  },
  {
    monolith: 'docs/plan/pillar-0-governance/audit-runner.md',
    slices_dir: 'docs/plan/pillar-0-governance/audit-runner',
    split_cmd: 'pnpm audit-runner:split',
    name: 'audit-runner',
  },
  {
    monolith: 'packages/principles/principles.yaml',
    slices_dir: 'packages/principles/principles',
    split_cmd: 'pnpm principles:split',
    name: 'principles',
  },
  {
    monolith: 'docs/plan/pillar-0-governance/ai-behavior-spine.md',
    slices_dir: 'docs/plan/pillar-0-governance/ai-behavior-spine',
    split_cmd: 'pnpm ai-behavior-spine:split',
    name: 'ai-behavior-spine',
  },
];

function getNewestSliceMtime(slicesDir) {
  if (!existsSync(slicesDir)) return 0;
  const files = readdirSync(slicesDir).filter(f => f.endsWith('.md') || f.endsWith('.yaml'));
  if (files.length === 0) return 0;
  return Math.max(...files.map(f => statSync(join(slicesDir, f)).mtimeMs));
}

async function main() {
  const warnings = [];
  let checked = 0;

  for (const pair of MONOLITH_SLICE_PAIRS) {
    const monolithPath = join(ROOT, pair.monolith);
    const slicesDirPath = join(ROOT, pair.slices_dir);

    if (!existsSync(monolithPath)) continue;
    checked++;

    const monolithMtime = statSync(monolithPath).mtimeMs;
    const newestSliceMtime = getNewestSliceMtime(slicesDirPath);

    if (newestSliceMtime === 0) {
      warnings.push(`${pair.name}: slices directory empty or missing — run \`${pair.split_cmd}\``);
    } else if (monolithMtime > newestSliceMtime + 5000) {
      // 5s grace period for simultaneous writes
      const monolithAge = new Date(monolithMtime).toISOString();
      const sliceAge = new Date(newestSliceMtime).toISOString();
      warnings.push(
        `${pair.name}: monolith modified ${monolithAge} but newest slice is ${sliceAge}\n` +
        `  → Run \`${pair.split_cmd}\` to sync slices`
      );
    }
  }

  if (warnings.length > 0) {
    console.warn(`\n${warnings.length} warning(s) — stale slices detected:`);
    for (const w of warnings) console.warn(`  ⚠ ${w}`);
  }

  const summary = `[validate-slice-freshness] pairs_checked=${checked} stale=${warnings.length}`;
  console.log(`\n${summary}`);

  if (warnings.length > 0) process.exit(1);
  process.exit(0);
}

main().catch(err => { console.error('[validate-slice-freshness] fatal:', err); process.exit(1); });
